local msg = nil
local msgTimer = 0

-- Captions: British English, only what the plot needs. Long text is broken into lines of at most CDV.WRAP characters
-- (so that nothing is cut at the sides) and a caption of several lines is lifted so that it stays on screen.
CDV.WRAP = 46
function CDV.Wrap(text, width)
    local lines, line = {}, ""
    for word in tostring(text):gmatch("%S+") do
        if #line > 0 and #line + 1 + #word > width then
            lines[#lines + 1] = line
            line = word
        else
            line = (#line > 0) and (line .. " " .. word) or word
        end
    end
    if #line > 0 then lines[#lines + 1] = line end
    return table.concat(lines, "\n"), #lines
end
function CDV.Say(text, seconds)
    if RIP.attivo then return end
    if text == nil or text == "" then return end
    -- A caption is shown once in the whole game: once on screen it counts as read and never comes back.
    -- Remembered in GameVars (kept through levels and saved games) under a short key made from the text.
    local h = 5381
    for i = 1, #text do h = (h * 33 + text:byte(i)) % 2147483647 end
    local key = "c" .. h
    if GameVars.CDV_read == nil then GameVars.CDV_read = {} end
    if GameVars.CDV_read[key] then return end
    GameVars.CDV_read[key] = true
    if msg ~= nil then
        TEN.Strings.HideString(msg)
    end
    local wrapped, n = CDV.Wrap(text, CDV.WRAP)
    local x, y = TEN.Util.PercentToScreen(50, 86 - 4.2 * math.max(1, n))
    msg = TEN.Strings.DisplayString(wrapped, TEN.Vec2(x, y), 0.8, TEN.Color(255, 244, 214), false,
        { TEN.Strings.DisplayStringOption.CENTER, TEN.Strings.DisplayStringOption.SHADOW })
    TEN.Strings.ShowString(msg, seconds or 6)
end

function CDV.M(name)
    local ok, m = pcall(TEN.Objects.GetMoveableByName, name)
    if ok then return m end
    return nil
end

function CDV.Dead(name)
    local m = CDV.M(name)
    if m == nil then return true end
    if not m:GetValid() then return true end
    return m:GetHP() <= 0
end

function CDV.Active(name)
    local m = CDV.M(name)
    return m ~= nil and m:GetValid() and m:GetActive()
end

-- Levers (wall levers, SWITCH_TYPE4) toggle between two states: "pulled" = not in the state it had at start.
function CDV.Pulled(name)
    local m = CDV.M(name)
    if m == nil or not m:GetValid() then return false end
    local k = "s0_" .. name
    local s0 = CDV.Flag(k)
    if s0 == nil then
        s0 = m:GetState()
        CDV.Flag(k, s0)
    end
    return m:GetState() ~= s0
end

-- Two levers to be pulled within `frames` of each other (TEN levers toggle, so every pull is an event:
-- a late player simply pulls one again). Solved once; fn runs then.
function CDV.TwinLevers(id, a, b, frames, msgFirst, msgLate, fn)
    local rest = {}
    CDV.Loop(function()
        if CDV.Flag(id .. "_ok") then return end
        local now = (CDV.Flag(id .. "_t") or 0) + 1
        CDV.Flag(id .. "_t", now)
        for _, n in ipairs({a, b}) do
            local m = CDV.M(n)
            if m ~= nil and m:GetValid() then
                local t0 = CDV.Flag(id .. "_e_" .. n)
                local used = CDV.Used(n)
                if not t0 and rest[n] == nil and not used then
                    rest[n] = { anim = m:GetAnim(), state = m:GetState() }          -- the lever as it stands unpulled
                end
                if t0 and now - t0 > frames then                                    -- time is up: it springs back
                    CDV.Flag(id .. "_e_" .. n, false)
                    if rest[n] ~= nil then
                        pcall(function() m:SetAnim(rest[n].anim); m:SetState(rest[n].state) end)
                    end
                    pcall(function() m:SetStatus(TEN.Objects.MoveableStatus.INACTIVE) end)
                    CDV.Log("LEVER " .. n .. " back, time up")
                    CDV.Say(msgLate, 5)
                elseif used then
                    CDV.Rearm(n)
                    local other = (n == a) and b or a
                    local to = CDV.Flag(id .. "_e_" .. other)
                    if to and now - to <= frames then
                        CDV.Flag(id .. "_ok", true)
                        fn()
                        return
                    end
                    CDV.Flag(id .. "_e_" .. n, now)
                    CDV.Say(msgFirst, 4)
                end
            end
        end
    end)
end

function CDV.Enable(name)
    local m = CDV.M(name)
    if m ~= nil and m:GetValid() then m:Enable() end
end

function CDV.Disable(name)
    local m = CDV.M(name)
    if m ~= nil and m:GetValid() then m:Disable() end
end

-- Run fn after a number of frames (30 = 1 s). Not saved: use only for short visual sequences.
local timers = {}
function CDV.After(frames, fn) timers[#timers + 1] = { t = frames, fn = fn } end
-- An earthquake that can be seen: strength s*5 (150 at most) held for s*2 frames, then the engine lets it die away.
function CDV.Quake(s)
    local n, str = s * 2, math.min(150, s * 5)
    local function go()
        pcall(function() TEN.Effects.MakeEarthquake(str) end)
        n = n - 1
        if n > 0 then CDV.After(1, go) end
    end
    go()
end

local function TimersTick()
    for i = #timers, 1, -1 do
        local t = timers[i]
        t.t = t.t - 1
        if t.t <= 0 then table.remove(timers, i); t.fn() end
    end
end

-- Key into a lock moveable, scripted: Lara steps to the plate, plays the native "use key" animation,
-- then the target (a door) is enabled as if triggered.
function CDV.InsertKey(lockName, targetName, leafName)
    local lock = CDV.M(lockName)
    if lock ~= nil and lock:GetValid() then
        local lp = lock:GetPosition()
        local yaw = lock:GetRotation().y
        local a = math.rad(yaw)
        Lara:SetPosition(TEN.Vec3(lp.x + math.sin(a) * 312, lp.y, lp.z + math.cos(a) * 312), false)
        Lara:SetRotation(TEN.Rotation(0, yaw, 0))
        Lara:SetAnim(131)
        Lara:SetState(42)
    end
    CDV.After(45, function()
        CDV.Enable(targetName)
        if leafName then CDV.Swing(leafName, "y", 90, 40) end
    end)
end

-- Turn a named static about its own origin (hinged leaves and hatches): axis "x", "y" or "z",
-- `by` degrees over `frames` frames.
function CDV.Swing(name, axis, by, frames)
    local ok, st = pcall(TEN.Objects.GetStaticByName, name)
    if not ok or st == nil then return end
    local r0 = st:GetRotation()
    local start = { x = r0.x, y = r0.y, z = r0.z }
    local f = 0
    local function step()
        f = f + 1
        local t = math.min(f / frames, 1.0)
        local r = { x = start.x, y = start.y, z = start.z }
        r[axis] = start[axis] + by * (1 - (1 - t) * (1 - t))
        st:SetRotation(TEN.Rotation(r.x, r.y, r.z))
        if f < frames then CDV.After(1, step) end
    end
    CDV.After(1, step)
end

-- Hands: a key or a device is never used with a weapon drawn. Lara puts it away first.
function CDV.HandsFree()
    local ok, free = pcall(function() return Lara:GetHandStatus() == TEN.Objects.HandStatus.FREE end)
    return (not ok) or free
end
function CDV.Holster()
