local rip = { t = 0, cur = 0, wait = 60 }
local function RipreseTick()
    if not RIP.attivo or CDV.SHOTS == 0 then return end
    if TEN.View.GetCameraType() == TEN.View.CameraType.FLYBY then
        rip.wait = 45
        return
    end
    if rip.wait > 0 then
        rip.wait = rip.wait - 1
        return
    end
    local first = RIP.solo or 1
    local last = RIP.solo or CDV.SHOTS
    if rip.cur == 0 then
        rip.cur = first
    else
        rip.cur = rip.cur + 1
        if rip.cur > last then
            if not RIP.ciclo then
                rip.cur = last + 1
                rip.wait = 1e9
                return
            end
            rip.cur = first
        end
    end
    TEN.View.PlayFlyby(rip.cur)
end
CDV.RipreseTick = RipreseTick

function CDV.Tick()
    armedClock = armedClock + 1
    local S = St()
    TimersTick()
    RipreseTick()
    TeleportStep()
    for _, z in ipairs(zones) do
        if not (z.once and S.done[z.id]) then
            if (z.need == nil or z.need()) and CDV.Near(z.x, z.y, z.z, z.r, z.dy) then
                if z.once then S.done[z.id] = true end
                if z.text then CDV.Say(z.text, z.secs) end
                CDV.Cue(z.id)
                if z.fn then z.fn() end
            end
        end
    end
    for _, d in ipairs(drops) do
        if not S.done["drop_" .. d.id] and CDV.Dead(d.enemy) then
            S.done["drop_" .. d.id] = true
            CDV.Cue("drop_" .. d.id)
            CDV.Give(d.item, 1)
            if d.text then CDV.Say(d.text, 6) end
        end
    end
    -- A secret is a Star of the Dioscuri lying at its place ("stella_<index>", PUZZLE_ITEM16): it is found when she
    -- picks the star up. The star goes out of the inventory at once; until then it glimmers when she is near.
    -- In a level compiled without the stars a secret is still found by walking onto its place.
    local stars = false
    for _, s in ipairs(secrets) do
        if CDV.M("stella_" .. s.index) ~= nil then stars = true end
    end
    local function found(s)
        S.secrets["s" .. s.index] = true
        TEN.Flow.AddSecret(s.index)
        CDV.Cue("segreto")
        CDV.Say(s.text or "", 5)
        if s.give then CDV.Give(s.give, 1) end
        local all = true
        for _, q in ipairs(secrets) do if not S.secrets["s" .. q.index] then all = false end end
        if all and CDV.STAR_REWARD and not S.done["premio_stelle"] then      -- 20 Nov: every Star of the level
            S.done["premio_stelle"] = true
            for _, g in ipairs(CDV.STAR_REWARD) do CDV.Give(g[1], g[2]) end
            CDV.After(120, function() CDV.Say(CDV.STAR_TEXT, 7) end)
        end
    end
    if stars then
        local lp = Lara:GetPosition()
        local ok, got = pcall(TEN.Inventory.GetItemCount, ID.PUZZLE_ITEM16)
        if ok and got ~= nil and got > 0 then
            pcall(TEN.Inventory.TakeItem, ID.PUZZLE_ITEM16, got)
            local best, bd = nil, 1e18
            for _, s in ipairs(secrets) do
                local d = (lp.x - s.x) ^ 2 + (lp.y - s.y) ^ 2 + (lp.z - s.z) ^ 2
                if not S.secrets["s" .. s.index] and d < bd then best, bd = s, d end
            end
            if best ~= nil then found(best) end
        end
        CDV.starTick = (CDV.starTick or 0) + 1
        for _, s in ipairs(secrets) do
            if not S.secrets["s" .. s.index] and math.abs(lp.x - s.x) < 10240 and math.abs(lp.z - s.z) < 10240 then
                local k = 0.6 + 0.4 * math.sin(CDV.starTick / 9)
                pcall(function()
                    TEN.Effects.EmitLight(TEN.Vec3(s.x, s.y - 160, s.z), TEN.Color(math.floor(210 * k), math.floor(225 * k), math.floor(255 * k)), 5, false, "cdv_stella_" .. s.index)
                end)
            end
        end
    else
        for _, s in ipairs(secrets) do
            if not S.secrets["s" .. s.index] and CDV.Near(s.x, s.y, s.z, s.r, 1024) then found(s) end
        end
    end
    for _, f in ipairs(loops) do f() end
end

function CDV.UseItem(again)
    local S = St()
    local item = again or TEN.Inventory.GetUsedItem()
    if Lara:GetState() ~= 2 then                     -- in the air, running, climbing: nothing is used
        for _, u in ipairs(uses) do
            if item == u.item then TEN.Inventory.ClearUsedItem() return end
        end
    end
    if not CDV.HandsFree() then
        for _, u in ipairs(uses) do
            if item == u.item then          -- weapon in hand: refused
                TEN.Inventory.ClearUsedItem()
                CDV.Armed()
                return
            end
        end
    end
    for _, u in ipairs(uses) do
        local ux, uy, uz = u.x, u.y, u.z
        if u.near then
            local m = CDV.M(u.near)
            if m ~= nil and m:GetValid() then local q = m:GetPosition(); ux, uy, uz = q.x, q.y, q.z end
        end
        if item == u.item and not S.done["use_" .. u.id] and CDV.Near(ux, uy, uz, u.r, u.dy) and CDV.FrontOk("use_" .. u.id) then
            if u.need == nil or u.need() then
                TEN.Inventory.ClearUsedItem()
                S.done["use_" .. u.id] = true
                if u.consume then CDV.Take(u.item) end
                if u.text then CDV.Say(u.text, u.secs or 7) end
                CDV.CueAfterAnim("use_" .. u.id)
                CDV.FrontSnap("use_" .. u.id)
                if u.fn then u.fn() end
                return
            elseif u.fail then
                TEN.Inventory.ClearUsedItem()
                CDV.Say(u.fail, 6)
                return
            end
        end
    end
end

