    use_chiusa = "tr3_26_seeing_is_believing_1",      -- manovella: il Mergolo si svuota
    fondo = "tr2_11_incidental_5",                -- sul fondo del Mergolo
    canneto = "tr3_14_butterflies_2",            -- oltre il cancello
    casello = "tr3_45_look_out_5",          -- il Baddy 2 nel casello
    chiave_casello = "tr3_28_look_what_we_have_here_1",          -- il Baddy 2 lascia la chiave
    use_chiusa2 = "tr2_12_incidental_6",     -- la chiusa grande si apre
    g1 = "tr3_40_stone_the_crows_10",                  -- sotto la rupe
    canto_ok = "tr3_27_seeing_is_believing_2",                -- le cinque conchiglie in ordine
    laghetto = "tr3_15_butterflies_3",          -- il laghetto di Donna Villa
    masso_g = "tr3_43_look_out_3",                  -- il masso
    dopo_massi = "tr3_08_long_way_up",           -- when the three boulders have come to rest
    -- scala: no cue of its own any more, the music of the way up starts after the boulders (Ed, 16/11)
    segreto = "tr2_25_secret",                -- ogni Stella dei Dioscuri
}
local cued = {}
function CDV.Cue(id)
    local f = CDV.MUSIC[id]
    if f == nil or (cued[id] and id ~= "segreto") then return end
    cued[id] = true
    if CDV.Log then CDV.Log("CUE " .. id .. " -> " .. f) end
    CDV.Track(f)
end


-- The cue of a used item waits for Lara's animation to end (key 131, insert 134, valve 470), unless the level plays
-- it itself at its own moment (CDV.CUE_MANUAL).
CDV.CUE_MANUAL = CDV.CUE_MANUAL or {}
CDV.CUE_MANUAL["use_chiusa2"] = true          -- played by CDV.OpenSluice when the flyby starts
CDV.GATE_SFX = 221          -- TR4_Metal_Gate_Open
local USE_ANIMS = { [131] = true, [134] = true, [470] = true }
function CDV.CueAfterAnim(id)
    if CDV.MUSIC[id] == nil or CDV.CUE_MANUAL[id] then return end
    local n = 0
    local function wait()
        n = n + 1
        if n < 300 and (n < 25 or USE_ANIMS[Lara:GetAnim()]) then CDV.After(1, wait); return end
        CDV.Cue(id)
    end
    CDV.After(1, wait)
end
function CDV.GateSound()
    CDV.Sfx(CDV.GATE_SFX)
end

function CDV.End(levelIndex, startPos)
    TEN.Flow.EndLevel(levelIndex, startPos)
end

-- Lines "[CDV] ..." in Engine\Logs\TENLog_*.txt: what switches and doors did, frame by frame.
local frameNo = 0
function CDV.Log(text)
    pcall(function() TEN.Util.PrintLog("[CDV] f" .. frameNo .. " " .. text, TEN.Util.LogLevel.INFO, true) end)
end
local watched, watchLast, watchList = {}, {}, {}
function CDV.Watch(name)
    if not watched[name] then watched[name] = true; watchList[#watchList + 1] = name end
end

-- True on the frame Lara starts working the switch `name`: she is at it (the engine puts her about 310 units in
-- front of the item) and plays a switch animation. The state of the switch item is not used: it is only logged.
local SWITCH_STATES = { [40] = true, [41] = true }                       -- LS_SWITCH_DOWN, LS_SWITCH_UP
local SWITCH_ANIMS = { [63] = true, [64] = true, [195] = true, [196] = true, [197] = true }
local using = {}
function CDV.Used(name)
    CDV.Watch(name)
    local m = CDV.M(name)
    if m == nil or not m:GetValid() then return false end
    local q, p = m:GetPosition(), Lara:GetPosition()
    local near = (p.x - q.x) ^ 2 + (p.z - q.z) ^ 2 <= 560 ^ 2 and math.abs(p.y - q.y) <= 300
    local now = near and (SWITCH_STATES[Lara:GetState()] == true or SWITCH_ANIMS[Lara:GetAnim()] == true)
    local was = using[name]
    using[name] = now
    if now and not was then
        CDV.Log("USED " .. name .. " lara anim " .. Lara:GetAnim() .. " state " .. Lara:GetState())
        return true
    end
    return false
end

-- A wall switch that opens a door, once. The switch is native (Lara's animation, the on-screen prompt).
function CDV.SwitchDoor(switchName, doorName, fn)
    CDV.Watch(doorName)
    CDV.Loop(function()
        if CDV.Flag("aperta_" .. doorName) then return end
        if not CDV.Used(switchName) then return end
        CDV.Flag("aperta_" .. doorName, true)
        CDV.After(25, function()
            CDV.Log("OPEN " .. doorName)
            CDV.Enable(doorName)
            if fn then fn() end
        end)
    end)
end

-- Kick door. side "A" (house doors, CdV_Porte): the item stands in the room the door opens into, its leaf 492
-- units behind it; Lara kicks from the other side of the leaf. side "B" (the wooden DOOR_TYPE1): the leaf is behind
-- the item too, but swings away from it: Lara kicks standing by the item.
CDV.KICK_FRAMES = 10      -- frames from Action to the door being released: Lara's foot lands around frame 12
function CDV.KickDoor(doorName, fn, side)
    CDV.Watch(doorName)
    CDV.Loop(function()
        if CDV.Flag("aperta_" .. doorName) then return end
        local d = CDV.M(doorName)
        if d == nil or not d:GetValid() then return end
        local q, p = d:GetPosition(), Lara:GetPosition()
        if math.abs(p.y - q.y) > 200 then return end
        local yaw = d:GetRotation().y
        local a = math.rad(yaw)
        local back, face = 917, yaw
        if side == "B" then back, face = 109, (yaw + 180) % 360 end
        local sx, sz = q.x - back * math.sin(a), q.z - back * math.cos(a)
        if (p.x - sx) ^ 2 + (p.z - sz) ^ 2 > 520 ^ 2 then
            -- 26 Nov: the other side too, so that nobody stays shut in behind a door that opened from one side only
            if side == "B" then back, face = 917, yaw else back, face = 109, (yaw + 180) % 360 end
            sx, sz = q.x - back * math.sin(a), q.z - back * math.cos(a)
            if (p.x - sx) ^ 2 + (p.z - sz) ^ 2 > 520 ^ 2 then return end
        end
        if not CDV.Flag("calcio_detto") then
            CDV.Flag("calcio_detto", true)
            CDV.Say("Face the door and press Action to kick it open.", 5)
        end
        if not TEN.Input.IsKeyHit(TEN.Input.ActionID.ACTION) then return end
        if Lara:GetState() ~= 2 then return end
        if not CDV.HandsFree() then CDV.Armed() return end
        local dyaw = math.abs(((Lara:GetRotation().y - face) + 540) % 360 - 180)
        if dyaw > 40 then return end
        CDV.Flag("aperta_" .. doorName, true)
        CDV.Log("KICK " .. doorName)
        Lara:SetPosition(TEN.Vec3(math.floor(sx), q.y, math.floor(sz)), false)
        Lara:SetRotation(TEN.Rotation(0, face, 0))
        Lara:SetAnim(315)
        CDV.After(CDV.KICK_FRAMES, function()
            CDV.Enable(doorName)
            if fn then fn() end
        end)
    end)
end

-- The Seal is pressed into the plate: Lara in front of it, the insert animation, then fn.
function CDV.ShowModel(name, on)
    local m = CDV.M(name)
    if m == nil or not m:GetValid() then return end
    pcall(function() for i = 0, m:GetMeshCount() - 1 do m:SetMeshVisible(i, on) end end)
end
function CDV.InsertSeal(plateName, sealName, fn)
    local pl = CDV.M(plateName)
    if pl ~= nil and pl:GetValid() then
        local lp = pl:GetPosition()
        local yaw = pl:GetRotation().y
        local a = math.rad(yaw)
        Lara:SetPosition(TEN.Vec3(lp.x + math.sin(a) * 312, lp.y, lp.z + math.cos(a) * 312), false)
        Lara:SetRotation(TEN.Rotation(0, yaw, 0))
        CDV.PuzzleAnim()           -- the insert animation, frame 80 skipped
    end
    CDV.Log("SEAL start at " .. plateName)
    local waited = 0
    local function done()
        waited = waited + 1
        if waited < 200 and (waited < 20 or Lara:GetAnim() == 134) then CDV.After(1, done); return end
        CDV.Log("SEAL in " .. plateName .. " after " .. waited .. " frames")
        CDV.ShowModel(sealName, true)                 -- only now: Lara has taken her hand away
        if fn then fn() end
    end
    CDV.After(1, done)
end

-- The crank goes on the winch and Lara turns it: the valve animation (470, a switch state), the crank `name`
-- shows up when her hands reach it and turns about its own axis, then fn. CDV.CRANK_DIST is how far from the
-- crank's axis she stands.
CDV.CRANK_DIST = 400
function CDV.Ghost(name)
    local m = CDV.M(name)
    if m == nil or not m:GetValid() then return end
    pcall(function() m:SetCollidable(false) end)
    CDV.ShowModel(name, false)
end
function CDV.TurnCrank(name, fn)
    local m = CDV.M(name)
    if m == nil or not m:GetValid() then
        CDV.Log("CRANK: no moveable " .. name)
        if fn then fn() end
        return
    end
    local p = m:GetPosition()
    local r0 = m:GetRotation()
    local a = math.rad(r0.y)
    local lp = Lara:GetPosition()
    Lara:SetPosition(TEN.Vec3(math.floor(p.x - math.sin(a) * CDV.CRANK_DIST), lp.y, math.floor(p.z - math.cos(a) * CDV.CRANK_DIST)), false)
    Lara:SetRotation(TEN.Rotation(0, r0.y, 0))
    Lara:SetAnim(470)              -- LA_VALVE_TURN
    Lara:SetState(40)
    CDV.Log("CRANK start, lara anim " .. Lara:GetAnim())
    local f = 0
    local function step()
        f = f + 1
        if f == 24 then CDV.ShowModel(name, true); CDV.Log("CRANK shown") end
        if f > 40 and f <= 150 then
            local t = (f - 40) / 110
            pcall(function() m:SetRotation(TEN.Rotation(r0.x, r0.y, (r0.z - 1080 * t) % 360)) end)
        end
        if f < 220 and (f < 152 or Lara:GetAnim() == 470) then CDV.After(1, step); return end
        CDV.Log("CRANK done after " .. f .. " frames")
        if fn then fn() end
    end
    CDV.After(1, step)
end

-- The big sluice: Lara turns the key, the gate `gateName` goes up `rise` units with mist on both its sides and a
-- tremor, the screen fades, fn (the flip of the lake), the screen comes back.
local canalRun = 0
-- The trickle in the channel (statics of CdV_Rivolo.wad2, in the room and in its flooded twin): upstream of the gate it
-- is always there, downstream once the sluice is open. The sheets slide one tile (512) towards the lake and jump back.
local RIV = { monte = 59904, valle = 55808 }
local function Riv(name, fn)
    for _, suf in ipairs({ "", "_pieno" }) do
        local ok, st = pcall(TEN.Objects.GetStaticByName, "rivolo_" .. name .. suf)
        if ok and st ~= nil then pcall(fn, st) end
    end
end
local function RivState()
    local open = CDV.Flag("canale_pieno") == true
    Riv("valle", function(st) if open then st:Enable() else st:Disable() end end)
    Riv("vasca", function(st) if open then st:Disable() else st:Enable() end end)
end
CDV.StartList = CDV.StartList or {}
CDV.StartList[#CDV.StartList + 1] = RivState
CDV.Loop(function()
    canalRun = (canalRun + 14) % 512
    Riv("monte", function(st) st:SetPosition(TEN.Vec3(12800, -168, RIV.monte - canalRun)) end)
    if CDV.Flag("canale_pieno") or CDV.Flag("canale_apre") then
        Riv("valle", function(st) st:SetPosition(TEN.Vec3(12800, -168, RIV.valle - canalRun)) end)
    end
end)

function CDV.OpenSluice(gateName, rise, fn)
    local g = CDV.M(gateName)
    if g ~= nil and not g:GetValid() then g = nil end
    local p0 = g and g:GetPosition() or nil
    local wt = CDV.M("acqua_canale")
    if wt ~= nil and not wt:GetValid() then wt = nil end
    local w0 = wt and wt:GetPosition() or nil
    Lara:SetAnim(131)              -- she stays turned as she is: towards the lock she pressed Action at
    Lara:SetState(42)
    CDV.Log("SLUICE key, gate " .. tostring(p0 ~= nil) .. ", water " .. tostring(w0 ~= nil))
    local f = 0
    local function step()
        f = f + 1
        if f >= 110 and f <= 230 and p0 ~= nil then
            local t = (f - 110) / 120
            pcall(function() g:SetPosition(TEN.Vec3(p0.x, p0.y - rise * t, p0.z)) end)
            if f % 3 == 0 then
                for _, dz in ipairs({ -260, 260 }) do
                    for _, dx in ipairs({ -500, 0, 500 }) do
                        pcall(function() TEN.Effects.EmitWaterfallMist(TEN.Vec3(p0.x + dx, p0.y - 60, p0.z + dz), 200, 160, 0, TEN.Color(210, 230, 235)) end)
                    end
                end
            end
        end
        if f == 150 then                -- the gate is a third of the way up: the water runs under it, down to the lake
            CDV.Flag("canale_apre", true)
            Riv("valle", function(st) st:Enable() end)
            Riv("vasca", function(st) st:Disable() end)
        end
        if f == 110 then CDV.Flyby(2) end
        if f == 116 then CDV.Cue("use_chiusa2") end          -- the sea coming in, with the pictures of it
        if f == 110 then CDV.Sfx(105); CDV.Log("SLUICE gate rising") end
        if f >= 110 and f <= 250 and f % 12 == 0 then CDV.Quake(18) end
        if f == 215 then pcall(function() TEN.View.FadeOut(1.2) end) end
        if f == 262 then
            CDV.Log("SLUICE flip")
            if fn then fn() end
            CDV.Flag("canale_pieno", true)          -- from now on the water runs downstream too
            RivState()
            pcall(function() TEN.View.FadeIn(0.8) end)
            return
        end
        CDV.After(1, step)
    end
    CDV.After(1, step)
end

-- A flyby sequence of the level, if this .ten has the cameras (they came with the shaft of the way out).
function CDV.Flyby(seq)
    local ok, room = pcall(TEN.Objects.GetRoomByName, "G6_POZZO_0")
    if not ok or room == nil then CDV.Log("FLYBY " .. seq .. ": level not compiled with the cameras"); return end
    CDV.Log("FLYBY " .. seq)
    pcall(function() TEN.View.PlayFlyby(seq) end)
end

-- A switch used without a floor trigger stays "active" after the first pull and TEN ignores Action on it: put it
-- back to inactive when its animation is over, so that it can be pulled again.
function CDV.Rearm(name, frames)
    CDV.After(frames or 90, function()
        local m = CDV.M(name)
        if m ~= nil and m:GetValid() then pcall(function() m:SetStatus(TEN.Objects.MoveableStatus.INACTIVE) end) end
    end)
end

local laraLast = ""
local function WatchTick()
    frameNo = frameNo + 1
    local p = Lara:GetPosition()
    local close = false
    for _, n in ipairs(watchList) do
        local m = CDV.M(n)
        if m ~= nil and m:GetValid() then
            local v = "st " .. tostring(m:GetState()) .. " tg " .. tostring(m:GetTargetState()) .. " " .. tostring(m:GetStatus()) .. " act " .. tostring(m:GetActive())
            if watchLast[n] ~= v then
                watchLast[n] = v
                CDV.Log(n .. ": " .. v .. " | lara " .. math.floor(p.x) .. " " .. math.floor(p.y) .. " " .. math.floor(p.z))
            end
            local q = m:GetPosition()
            if (p.x - q.x) ^ 2 + (p.z - q.z) ^ 2 <= 700 ^ 2 and math.abs(p.y - q.y) <= 300 then close = n end
        end
    end
    if close then
        local v = close .. " anim " .. Lara:GetAnim() .. " state " .. Lara:GetState() .. " hands " .. tostring(Lara:GetHandStatus())
        if v ~= laraLast then laraLast = v; CDV.Log("lara near " .. v .. " yaw " .. math.floor(Lara:GetRotation().y)) end
    end
end
CDV.Loop(WatchTick)

-- A sound of the level's own list, heard at Lara's ears.
function CDV.Sfx(id)
    local ok = pcall(function() TEN.Sound.PlaySound(id, Lara:GetPosition()) end)
    if not ok then pcall(function() TEN.Sound.PlaySound(id) end) end
end

-- Coloured light for a while (30 frames = 1 s), fading out: one dynamic light per point, every frame.
local glows = {}
function CDV.Glow(points, r, g, b, frames, radius)
    glows[#glows + 1] = { pts = points, r = r, g = g, b = b, t = frames, n = frames, rad = radius or 24 }
end
local function GlowTick()
    for i = #glows, 1, -1 do
        local w = glows[i]
        local k = math.min(1.0, w.t / (w.n * 0.5))
        local c = TEN.Color(math.floor(w.r * k), math.floor(w.g * k), math.floor(w.b * k))
        for j, p in ipairs(w.pts) do
            TEN.Effects.EmitLight(TEN.Vec3(p[1], p[2], p[3]), c, w.rad, false, "cdv_glow_" .. i .. "_" .. j)
        end
        w.t = w.t - 1
        if w.t <= 0 then table.remove(glows, i) end
    end
end
CDV.Loop(GlowTick)

