-- Every enemy that is on its feet comes for Lara, however far away she is (tools/lua_caccia.py).
-- Enemies and the camera (tools/lua_nemici4.py).
-- Switching on: a walker woken by a door comes in at once; any other at once when the place where it stands is not
-- on screen, otherwise as soon as the camera looks away, two seconds at most. Always where it stands.
-- The hunt: a walker hunts once it has seen her (within SEE sectors with a clear line, or hurt). From then on it
-- is kept in attack mood and, when it stops getting closer, put on her trail behind her and out of sight - as
-- long as she is within LEASH sectors. Beyond that it gives up until it sees her again.
local WALKERS = { ["c1"] = true, ["c2"] = true, ["t1"] = true, ["t2"] = true, ["t3"] = true, ["t4"] = true, ["t5"] = true, ["t6"] = true, ["t_chiave"] = true }
local BY_DOOR = { ["t_chiave"] = true }
local SIGHT = 30 * 1024
local SEE, LEASH = 10 * 1024, 20 * 1024
local EnableNow = CDV.Enable
local trail, trailFrame, stuck, lastHP = {}, 0, {}, {}
CDV.Aware = {}
local function PointOnScreen(p)
    local ok, seen = pcall(function()
        local cp, ct = TEN.View.GetCameraPosition(), TEN.View.GetCameraTarget()
        local fx, fz, dx, dz = ct.x - cp.x, ct.z - cp.z, p.x - cp.x, p.z - cp.z
        local d, fl = math.sqrt(dx * dx + dz * dz), math.sqrt(fx * fx + fz * fz)
        if d > SIGHT then return false end
        if d > 1 and fl > 1 and (fx * dx + fz * dz) / (fl * d) < 0.42 then return false end      -- more than 65 degrees off
        local ok2, los = pcall(function()
            return TEN.Util.HasLineOfSight(TEN.View.GetCameraRoom():GetRoomNumber(), cp, TEN.Vec3(p.x, p.y - 700, p.z))
        end)
        if ok2 and los == false then return false end
        return true
    end)
    return ok and seen
end
local function Dist(a, b) return math.sqrt((a.x - b.x) ^ 2 + (a.z - b.z) ^ 2) + math.abs(a.y - b.y) end
-- the newest point of the trail at least three seconds old, three sectors or more from her, nearer than `within`
local function TrailPoint(lp, within)
    for i = #trail - 3, 1, -1 do
        local c = trail[i]
        local cd = Dist(c, lp)
        if cd >= 3 * 1024 and cd < within and not PointOnScreen(c) then return c, cd end
    end
    return nil
end
function CDV.Enable(name)
    local m = CDV.M(name)
    if not WALKERS[name] or BY_DOOR[name] or m == nil or not m:GetValid() or m:GetActive() then return EnableNow(name) end
    if not PointOnScreen(m:GetPosition()) then
        CDV.Log("ENEMY " .. name .. " in, out of sight")
        return EnableNow(name)
    end
    if LevelVars.CDV_wait == nil then LevelVars.CDV_wait = {} end
    if LevelVars.CDV_wait[name] == nil then LevelVars.CDV_wait[name] = 0 end
end
CDV.Loop(function()
    trailFrame = trailFrame + 1
    local lp = Lara:GetPosition()
    local w = LevelVars.CDV_wait
    if w ~= nil then
        for name, t in pairs(w) do
            local m = CDV.M(name)
            if m == nil or not m:GetValid() then
                w[name] = nil
            elseif t >= 60 or not PointOnScreen(m:GetPosition()) then
                w[name] = nil
                EnableNow(name)
                CDV.Log("ENEMY " .. name .. (t >= 60 and " in after 2 s, in sight" or " in, out of sight"))
            else
                w[name] = t + 1
            end
        end
    end
    if trailFrame % 30 ~= 0 or Lara:GetHP() <= 0 then return end
    local st = Lara:GetState()
    if st == 0 or st == 1 or st == 2 then
        trail[#trail + 1] = { x = lp.x, y = lp.y, z = lp.z, room = Lara:GetRoomNumber() }
        if #trail > 40 then table.remove(trail, 1) end
    end
    if LevelVars.CDV_aware == nil then LevelVars.CDV_aware = {} end
    CDV.Aware = LevelVars.CDV_aware
    for name, _ in pairs(WALKERS) do
        local m = CDV.M(name)
        if m ~= nil and m:GetValid() and m:GetActive() and m:GetHP() > 0 then
            local p = m:GetPosition()
            local flat = math.sqrt((p.x - lp.x) ^ 2 + (p.z - lp.z) ^ 2)
            local d = flat + math.abs(p.y - lp.y)
            local hp = m:GetHP()
            if not CDV.Aware[name] then
                local sees = false
                if lastHP[name] ~= nil and hp < lastHP[name] then
                    sees = true
                elseif flat < SEE and math.abs(p.y - lp.y) < 4 * 1024 then
                    pcall(function()
                        sees = TEN.Util.HasLineOfSight(m:GetRoomNumber(), TEN.Vec3(p.x, p.y - 700, p.z), TEN.Vec3(lp.x, lp.y - 700, lp.z)) == true
                    end)
                end
                if sees then
                    CDV.Aware[name] = true
                    CDV.Log("HUNT " .. name .. " has seen her, " .. math.floor(d / 1024) .. " sectors away")
                end
            elseif d > LEASH then
                CDV.Aware[name] = false
                stuck[name] = nil
                CDV.Log("HUNT " .. name .. " gives up, " .. math.floor(d / 1024) .. " sectors away")
            end
            lastHP[name] = hp
            if CDV.Aware[name] then
                local s = stuck[name] or { d = d, n = 0 }
                stuck[name] = s
                if d > 5 * 1024 and d > s.d - 256 then s.n = s.n + 1 else s.n = 0 end
                s.d = d
                if s.n >= 4 and not PointOnScreen(p) then
                    local c, cd = TrailPoint(lp, d - 1024)
                    if c ~= nil then
                        local ok = pcall(function()
                            m:SetPosition(TEN.Vec3(c.x, c.y, c.z), false)
                            m:SetRoomNumber(c.room)
                            m:SetRotation(TEN.Rotation(0, math.deg(math.atan(lp.x - c.x, lp.z - c.z)), 0))
                        end)
                        CDV.Log("HUNT " .. name .. (ok and " put on her trail, " or " could not be moved, ") .. math.floor(cd / 1024) .. " sectors behind")
                        s.n, s.d = 0, cd
                    end
                end
            end
        else
            stuck[name] = nil
        end
    end
end)

local HUNTERS = { "t5", "c2", "t6", "t_chiave", "t3", "t4", "t1", "c1", "t2", "pip_g1", "pip_g2", "pip_c0", "pip_c1", "pip_c2", "pip_c3", "bestia_acqua1", "bestia_acqua2", "bestia_acqua3", "bestia_acqua4", "bestia_acqua5" }
local HUNT_BATS = { ["pip_g1"] = true, ["pip_g2"] = true, ["pip_c0"] = true, ["pip_c1"] = true, ["pip_c2"] = true, ["pip_c3"] = true }
local huntFrame, huntSaid = 0, false
CDV.Loop(function()
    huntFrame = huntFrame + 1
    if huntFrame % 10 ~= 0 or Lara:GetHP() <= 0 then return end
    for _, name in ipairs(HUNTERS) do
        local m = CDV.M(name)
        if m ~= nil and m:GetValid() and m:GetActive() and m:GetHP() > 0 then
            local ok = pcall(function()
                local c = TEN.Objects.Creature(m)
                if WALKERS[name] and not CDV.Aware[name] then
                    -- it has not seen her: the engine's own mood (never forced). One that gave up is let go.
                    if CDV.Aware[name] == false then c:SetMood(TEN.Objects.MoodType.AUTO or TEN.Objects.MoodType.BORED) end
                else
                    c:SetMood(TEN.Objects.MoodType.ATTACK)
                end
                if HUNT_BATS[name] then c:SetHurtByPlayer(true) end
            end)
            if not huntSaid then
                huntSaid = true
                CDV.Log(ok and ("HUNT on, first " .. name) or "HUNT not available in this engine build")
            end
        end
    end
end)

if CDV_TEST ~= nil then CDV_TEST(CDV, zones, uses) end

-- Playtest hook: Engine\Scripts\CdvTest.lua -> return { Oliveri = { tp = {x, y, z, "ROOM", yaw}, give = {"KEY_ITEM1"} } }
local okT, TST = pcall(require, "CdvTest")
if not okT or type(TST) ~= "table" then TST = {} end
local function TestStart()
    local t = TST[CDV.KEY or ""]
    if t == nil then return end
    if t.tp then
        Lara:SetPosition(TEN.Vec3(t.tp[1], t.tp[2], t.tp[3]), false)
        local room = TEN.Objects.GetRoomByName(t.tp[4])
        if room ~= nil then Lara:SetRoomNumber(room:GetRoomNumber()) end
        if t.tp[5] then Lara:SetRotation(TEN.Rotation(0, t.tp[5], 0)) end
    end
    for _, name in ipairs(t.kill or {}) do
        local m = CDV.M(name)
        if m ~= nil and m:GetValid() then m:SetHP(0) end
    end
end

LevelFuncs.OnStart = function()
    if CDV.VIDEO then CDV.Video(CDV.VIDEO) end
    if CDV.Start then CDV.Start() end
    TestStart()
end
LevelFuncs.OnLoad = function() end
LevelFuncs.OnSave = function() end
local hudStr = nil
local testFrame = 0
local testInfo = ""
local function TestHud()
    local t = TST[CDV.KEY or ""]
    if t == nil then return end
    testFrame = testFrame + 1
    if testFrame == 10 then
        for _, name in ipairs(t.give or {}) do
            local id = TEN.Objects.ObjID[name]
            if id ~= nil then TEN.Inventory.GiveItem(id, 1, false); testInfo = testInfo .. " +" .. name
            else testInfo = testInfo .. " ?" .. name end
        end
    end
    if t.hold and testFrame >= t.hold[1] and testFrame <= t.hold[2] then   -- {from, to}: Action held by script
        TEN.Input.KeyPush(TEN.Input.ActionID.ACTION)
    end
    for _, k in ipairs(t.keys or {}) do     -- { "SPRINT", from, to }: any action held by script, for repeatable tests
        if testFrame >= k[2] and testFrame <= k[3] then TEN.Input.KeyPush(TEN.Input.ActionID[k[1]]) end
    end
    for _, j in ipairs(t.jumps or {}) do   -- { frame, x, y, z, "ROOM", yaw }: timed teleports for repeatable tests
        if testFrame == j[1] then
            Lara:SetPosition(TEN.Vec3(j[2], j[3], j[4]), false)
            local room = TEN.Objects.GetRoomByName(j[5])
            if room ~= nil then Lara:SetRoomNumber(room:GetRoomNumber()) end
            if j[6] then Lara:SetRotation(TEN.Rotation(0, j[6], 0)) end
        end
    end
    if not t.hud then return end
    local p = Lara:GetPosition()
    local r = Lara:GetRotation()
    local txt = string.format("x %d  y %d  z %d  yaw %d  room %d  sx %d sz %d  f %d a %d s %d%s", p.x, p.y, p.z, math.floor(r.y), Lara:GetRoomNumber(), math.floor(p.x / 1024), math.floor(p.z / 1024), testFrame, Lara:GetAnim(), Lara:GetState(), testInfo)
    if t.watch then
        local m = CDV.M(t.watch)
        if m ~= nil and m:GetValid() then
            local q = m:GetPosition()
            local a = math.rad(m:GetRotation().y)
            local dx, dz = p.x - q.x, p.z - q.z
            local rx = dx * math.cos(a) - dz * math.sin(a)
            local rz = dx * math.sin(a) + dz * math.cos(a)
            txt = txt .. string.format("\n%s rel x %d y %d z %d  rot %d", t.watch, math.floor(rx), p.y - q.y, math.floor(rz), math.floor(m:GetRotation().y))
        end
    end
    -- probe = {{x, y, z[, room number]}, ...}: engine floor/ceiling heights there (TEN.Collision.Probe, bridges included);
    -- slots = {"BRIDGE_TILT2", ...}: how many moveables of those slots exist in the level.
    for i, q in ipairs(t.probe or {}) do
        local ok, pr
        if q[4] then ok, pr = pcall(TEN.Collision.Probe, TEN.Vec3(q[1], q[2], q[3]), q[4])
        else ok, pr = pcall(TEN.Collision.Probe, TEN.Vec3(q[1], q[2], q[3])) end
        if ok and pr ~= nil then
            txt = txt .. string.format("\nP%d floor %s ceil %s %s", i, tostring(pr:GetFloorHeight()), tostring(pr:GetCeilingHeight()), pr:GetRoomName())
        else
            txt = txt .. string.format("\nP%d probe error", i)
        end
    end
    for _, n in ipairs(t.states or {}) do
        local m = CDV.M(n)
        if m ~= nil and m:GetValid() then
            txt = txt .. string.format("\n%s st %s tg %s %s act %s", n, tostring(m:GetState()), tostring(m:GetTargetState()), tostring(m:GetStatus()), tostring(m:GetActive()))
        else
            txt = txt .. "\n" .. n .. " ?"
        end
    end
    for _, s in ipairs(t.slots or {}) do
        local ok, l = pcall(TEN.Objects.GetMoveablesBySlot, TEN.Objects.ObjID[s])
        txt = txt .. string.format("\n%s: %s", s, ok and tostring(#l) or "error")
    end
    if hudStr == nil then
        local x, y = TEN.Util.PercentToScreen(2, 4)
        hudStr = TEN.Strings.DisplayString(txt, TEN.Vec2(x, y), 0.7, TEN.Color(255, 255, 0), false, {})
    else
        hudStr:SetKey(txt)
    end
    TEN.Strings.ShowString(hudStr, 1)
end
LevelFuncs.OnLoop = function()
    CDV.Tick()
    TestHud()
end
LevelFuncs.OnUseItem = function()
    CDV.UseItem()
end
LevelFuncs.OnEnd = function() end
